  function inferCategories(role){
    const title=(role.title||'').toLowerCase(), agency=(role.agency||'').toLowerCase();
    const tags=[];
    if(agency.includes('dot')) tags.push('Construction / Fieldwork');
    if(title.includes('eam')||title.includes('asset')) tags.push('Asset Management / Data');
    if(title.includes('mechanical')||title.includes('engineering intern')) tags.push('Mechanical Design');
    if(title.includes('aerospace')||title.includes('space')||agency.match(/space|aerospace|blue origin|spacex|anduril|rocket lab|firefly|hermeus|inversion|astranis|gravitics|amca|muon/)) tags.push('Aerospace');
    if(title.match(/vehicle|automotive|car|ev intern|powersports/)||agency.match(/tesla|rivian|lucid|ford|general motors|stellantis|honda|toyota|denso|oshkosh|polaris/)) tags.push('Automotive');
    if(title.includes('test')||title.includes('field')||title.includes('construction')) tags.push('Fieldwork / Test');
    if(agency==='mta') tags.push('Systems / Integration');
    return [...new Set(tags.length?tags:['General Engineering'])];
  }
