  if (!Array.isArray(data.roles)) data.roles=freshSeed;
  const knownIds=new Set(data.roles.map(r=>r.id));
  freshSeed.forEach(role=>{if(!knownIds.has(role.id))data.roles.push({...role});});
  data.roles.forEach(role=>{if(!Array.isArray(role.categories))role.categories=inferCategories(role);if(!role.locationType)role.locationType='unknown';});
